// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Como usar este guia","html":"<p>Este guia faz parte da formação da equipe para o uso da plataforma de reforço escolar da rede municipal. Ele pode ser lido de uma vez ou consultado por capítulo, quando surgir uma dúvida.</p><h3>Ao final, você será capaz de</h3><ul><li>Implantar a rede na plataforma, do cadastro das escolas à entrega dos acessos.</li><li>Manter os cadastros atualizados por planilha ou por integração.</li><li>Definir as regras de funcionamento da rede.</li><li>Ler os indicadores e identificar as escolas que precisam de apoio.</li><li>Organizar a formação das equipes das escolas.</li><li>Garantir o uso ético e a proteção dos dados em toda a rede.</li></ul><h3>Como estudar</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th><th>Tempo</th></tr></thead><tbody><tr><td>Leitura</td><td>Ler os capítulos 2 a 10 e acompanhar as figuras.</td><td>3 h</td></tr><tr><td>Prática</td><td>Percorrer o assistente de implantação e as telas de indicadores.</td><td>3 h</td></tr><tr><td>Governança</td><td>Ler os capítulos 11 a 13 com a equipe responsável por dados.</td><td>1 h</td></tr><tr><td>Verificação</td><td>Responder às questões do capítulo 15.</td><td>1 h</td></tr></tbody></table></div><div class=\"nota\"><b>Dados dos exemplos</b><br/>Os nomes, as turmas e os números usados nos exemplos e nos gráficos deste guia são fictícios. Eles servem para mostrar como ler as telas.</div>"},{"id":"c2","titulo":"O papel da Secretaria","html":"<p>A Secretaria administra a rede dentro da plataforma: cadastra escolas e equipes, define as regras de funcionamento e acompanha os resultados de todas as escolas.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Frente</th><th>O que a Secretaria faz</th><th>Onde, no menu</th></tr></thead><tbody><tr><td>Implantação</td><td>Cadastra escolas, servidores, turmas e alunos.</td><td>Implantação, Escolas, Turmas e alunos</td></tr><tr><td>Acessos</td><td>Convida as equipes e controla quem entra.</td><td>Servidores e convites, Login único</td></tr><tr><td>Regras</td><td>Define como a rede funciona.</td><td>Configurações</td></tr><tr><td>Resultados</td><td>Acompanha prática e recuperação de habilidades.</td><td>Visão geral, Indicadores, Habilidades prioritárias</td></tr><tr><td>Tecnologia</td><td>Liga a plataforma aos sistemas da Secretaria.</td><td>Integrações, Identidade da rede</td></tr><tr><td>Controle</td><td>Confere as ações realizadas.</td><td>Auditoria</td></tr></tbody></table></div>"},{"id":"c3","titulo":"Como o aluno estuda","html":"<p>O reforço é individual. Cada aluno entra com o próprio acesso, escolhe a matéria que quer estudar e segue um caminho montado para ele, em casa ou na escola, no tablet, no celular ou no computador.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Entrar</b><small>acesso individual entregue pela escola</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Diagnóstico</b><small>questões curtas por habilidade</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Trilha</b><small>cinco etapas por habilidade</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Tutor</b><small>dicas e perguntas, sem dar a resposta</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Evolução</b><small>três níveis de domínio</small></div></div><figcaption>Figura. O caminho do aluno no reforço.</figcaption></figure><h3>O diagnóstico</h3><p>O diagnóstico usa poucas questões por habilidade e para assim que tem segurança sobre o que o aluno sabe. Não é prova, não gera nota e não aparece para o aluno como aprovação ou reprovação.</p><h3>A trilha em cinco etapas</h3><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Relembrar</b><small>retoma o que o aluno já viu</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Exemplo guiado</b><small>mostra a resolução passo a passo</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Praticar</b><small>questões com retorno imediato</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Aplicar</b><small>situações do dia a dia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Explicar</b><small>o aluno explica com as próprias palavras</small></div></div><figcaption>Figura. As cinco etapas de cada trilha.</figcaption></figure><p>Cada resposta errada indica um tipo de dificuldade. A plataforma usa essa informação para escolher a dica e a próxima questão, em vez de apenas marcar certo ou errado.</p><h3>Os três níveis</h3><figure><div class=\"niveis\"><div class=\"nv\" style=\"background:#C44536\"><b>Ainda não</b><small>não mostrou domínio</small></div><div class=\"seta\">&#8250;</div><div class=\"nv\" style=\"background:#D9920B\"><b>Quase lá</b><small>acerta parte, precisa praticar</small></div><div class=\"seta\">&#8250;</div><div class=\"nv\" style=\"background:#1E8E5A\"><b>Domina</b><small>domínio consistente</small></div></div><figcaption>Figura. A evolução do aluno em cada habilidade.</figcaption></figure><h3>A volta ao que ficou para trás</h3><p>Muitas dificuldades vêm de um conteúdo de ano anterior. Quando o aluno erra, a plataforma verifica as habilidades que servem de base e leva o aluno a elas antes de seguir.</p><figure><div class=\"escada\"><div class=\"dg\" style=\"margin-left:0mm\"><span class=\"ano\">6º ano</span><span class=\"hab\">Resolver problemas com frações</span><span class=\"sit sn\">Ainda não</span></div><div class=\"dg\" style=\"margin-left:9mm\"><span class=\"ano\">5º ano</span><span class=\"hab\">Comparar e ordenar frações</span><span class=\"sit sq\">Quase lá</span></div><div class=\"dg\" style=\"margin-left:18mm\"><span class=\"ano\">4º ano</span><span class=\"hab\">Reconhecer frações unitárias</span><span class=\"sit sd\">Domina</span></div></div><figcaption>Figura. Exemplo: a dificuldade do 6º ano tem origem em uma habilidade do 5º ano. O aluno estuda primeiro a do 5º.</figcaption></figure><div class=\"nota\"><b>O reforço não depende da aula</b><br/>Ninguém da escola precisa liberar, aplicar ou corrigir nada para o reforço acontecer. A escola oferece o acesso e acompanha.</div>"},{"id":"c4","titulo":"Implantação da rede em oito etapas","html":"<p>O item <b>Implantação</b> abre um assistente que mostra o que já foi feito e o que falta. A maior parte do trabalho é feita por planilha.</p><figure><div class=\"tela\"><div class=\"barra\"><span></span><span></span><span></span><em>{{REDE}}</em></div><div class=\"app\"><aside><div class=\"logo\">{{REDE}}</div><div class=\"pf\">Gestor da rede</div><div class=\"it\">Visão geral</div><div class=\"it at\">Implantação</div><div class=\"it\">Escolas</div><div class=\"it\">Turmas e alunos</div><div class=\"it\">Servidores e convites</div><div class=\"it\">Diagnósticos</div><div class=\"it\">Habilidades prioritárias</div><div class=\"it\">Indicadores</div><div class=\"it\">Configurações</div></aside><main><div class=\"cab\"><b>Assistente de Implantação</b><small>Siga os passos para colocar a rede em funcionamento.</small></div><div class=\"corpo\"><div class=\"lst\"><div class=\"li\"><b>1. Escolas</b><small>38 escolas cadastradas</small><span class=\"bt\">Feito</span></div><div class=\"li\"><b>2. Ano letivo</b><small>2027, 4 períodos</small><span class=\"bt\">Feito</span></div><div class=\"li\"><b>3. Matérias</b><small>9 matérias da BNCC</small><span class=\"bt\">Feito</span></div><div class=\"li\"><b>4. Servidores</b><small>412 pessoas com acesso, 37 convites pendentes</small><span class=\"bt\">Abrir</span></div></div></div></main></div></div><figcaption>Ilustração da tela. O assistente lista as etapas e a situação de cada uma.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th><th>Dica</th></tr></thead><tbody><tr><td>1. Escolas</td><td>Cadastrar ou importar as escolas da rede.</td><td>Use o nome oficial e o código da escola.</td></tr><tr><td>2. Ano letivo</td><td>Criar o ano letivo e os períodos.</td><td>A configuração rápida cria os períodos.</td></tr><tr><td>3. Matérias</td><td>Trazer as matérias da BNCC.</td><td>A configuração rápida inclui todas.</td></tr><tr><td>4. Servidores</td><td>Importar direção, coordenação e professores e enviar os convites.</td><td>Confira os e-mails antes de importar.</td></tr><tr><td>5. Turmas e alunos</td><td>Importar as turmas e os alunos.</td><td>Importe uma escola como teste primeiro.</td></tr><tr><td>6. Professores nas turmas</td><td>Atribuir cada professor às turmas e matérias.</td><td>Sem isso, o professor não vê as turmas.</td></tr><tr><td>7. Cartões de acesso</td><td>Gerar o PDF dos cartões dos alunos e das fichas dos responsáveis.</td><td>Combine com as escolas o dia da entrega.</td></tr><tr><td>8. Revisão</td><td>Conferir se não há pendência crítica e concluir.</td><td>O assistente aponta o que falta.</td></tr></tbody></table></div><h3>Cronograma de referência</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Semana</th><th>Atividades</th><th>Responsável</th></tr></thead><tbody><tr><td>1</td><td>Etapas 1 a 3 e preparação das planilhas.</td><td>Secretaria</td></tr><tr><td>2</td><td>Etapas 4 a 6 e conferência com as escolas.</td><td>Secretaria e direções</td></tr><tr><td>3</td><td>Etapa 7, formação das equipes e entrega dos acessos.</td><td>Secretaria, direções e professores</td></tr><tr><td>4</td><td>Etapa 8, primeiro diagnóstico e início do reforço.</td><td>Coordenação pedagógica</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Qualidade do cadastro</b><br/>Aluno em turma errada ou professor sem atribuição gera a maior parte das dúvidas no início. Vale conferir uma escola por inteiro antes de importar as demais.</div>"},{"id":"c5","titulo":"O seu menu, tela por tela","html":"<div class=\"tb\"><table><thead><tr><th>No menu</th><th>Para que serve</th></tr></thead><tbody><tr><td>Visão geral</td><td>Situação da rede: prática na semana, uso por componente e pontos que precisam de atenção.</td></tr><tr><td>Implantação</td><td>Assistente com as oito etapas para colocar a rede em funcionamento.</td></tr><tr><td>Escolas</td><td>Cadastro e gestão das escolas da rede.</td></tr><tr><td>Turmas e alunos</td><td>Criação de turmas avulsas ou importação em massa por planilha.</td></tr><tr><td>Servidores e convites</td><td>Quem tem acesso à rede e os convites enviados.</td></tr><tr><td>Diagnósticos</td><td>Acompanhamento dos diagnósticos da rede. A coordenação cria e aplica.</td></tr><tr><td>Habilidades prioritárias</td><td>Habilidades com menor domínio na rede, por ano e componente.</td></tr><tr><td>Indicadores</td><td>Prática em casa e recuperação de habilidades, por escola e por período.</td></tr><tr><td>Configurações</td><td>Regras da rede.</td></tr><tr><td>Identidade da rede</td><td>Nome, logo e cores da rede em todas as telas.</td></tr><tr><td>Integrações</td><td>Chaves de acesso e endereços para troca de dados com outros sistemas.</td></tr><tr><td>Busca automática</td><td>Leitura diária da planilha publicada pelo sistema da Secretaria.</td></tr><tr><td>Login único</td><td>Entrada da equipe com a conta institucional que a rede já usa.</td></tr><tr><td>Retorno das famílias</td><td>O que os responsáveis disseram sobre os professores.</td></tr><tr><td>Formação</td><td>Este guia e os demais materiais de treinamento.</td></tr><tr><td>Auditoria</td><td>Registro das ações realizadas na rede.</td></tr></tbody></table></div>"},{"id":"c6","titulo":"Decisões de configuração","html":"<p>Em <b>Configurações</b>, a Secretaria define como a rede funciona. As principais decisões:</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Decisão</th><th>Opções</th><th>Recomendação</th></tr></thead><tbody><tr><td>Atribuição de trilha após o diagnóstico</td><td>Sugerir ao professor ou atribuir direto ao aluno.</td><td>Atribuir direto ao aluno mantém o reforço independente da escola.</td></tr><tr><td>Aprovação de trilha</td><td>Exigir ou não a aprovação da coordenação.</td><td>Exigir quando a rede quer padronizar o material criado pelos professores.</td></tr><tr><td>Diagnóstico com retorno ao pré-requisito</td><td>Ligado ou desligado.</td><td>Ligado: a plataforma inclui itens de anos anteriores quando o aluno erra, para achar a origem da dificuldade.</td></tr></tbody></table></div><div class=\"nota\"><b>Mudança de regra</b><br/>Uma mudança de configuração vale para toda a rede. Comunique às escolas antes de alterar.</div>"},{"id":"c7","titulo":"Integrações, login único e identidade","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Sistema da Secretaria</b><small>diário ou cadastro de alunos</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Integração</b><small>chave de acesso e conexão segura</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Plataforma</b><small>escolas, turmas e alunos atualizados</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Retorno</b><small>evolução dos alunos para o sistema da rede</small></div></div><figcaption>Figura. A troca de dados entre o sistema da Secretaria e a plataforma.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Recurso</th><th>Como funciona</th><th>Quem configura</th></tr></thead><tbody><tr><td>Integrações</td><td>A equipe técnica cadastra uma chave de acesso e o endereço do sistema externo. Toda troca usa conexão segura e fica registrada.</td><td>Equipe de tecnologia da Secretaria</td></tr><tr><td>Busca automática</td><td>A plataforma lê todo dia a planilha publicada pelo sistema da Secretaria e atualiza os cadastros.</td><td>Equipe de tecnologia da Secretaria</td></tr><tr><td>Importação por planilha</td><td>Escolas, servidores, turmas, alunos e atribuições em arquivo CSV ou XLSX.</td><td>Gestor da rede</td></tr><tr><td>Login único</td><td>Professores e gestores entram com a conta institucional, sem senha nova.</td><td>Equipe de tecnologia da Secretaria</td></tr><tr><td>Identidade da rede</td><td>Nome, logo e cores do Município em todas as telas, inclusive para alunos e responsáveis.</td><td>Gestor da rede</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Chaves de acesso</b><br/>A chave de integração dá acesso aos dados da rede. Guarde em local seguro, limite quem a conhece e troque quando alguém da equipe técnica sair.</div>"},{"id":"c8","titulo":"Como acompanhar a rede","html":"<p>Dois números resumem o reforço: quantos alunos praticaram e quantas habilidades foram recuperadas. Os dois aparecem por escola, nos últimos 7 ou 30 dias.</p><figure><div class=\"tela\"><div class=\"barra\"><span></span><span></span><span></span><em>{{REDE}}</em></div><div class=\"app\"><aside><div class=\"logo\">{{REDE}}</div><div class=\"pf\">Gestor da rede</div><div class=\"it at\">Visão geral</div><div class=\"it\">Implantação</div><div class=\"it\">Escolas</div><div class=\"it\">Turmas e alunos</div><div class=\"it\">Servidores e convites</div><div class=\"it\">Diagnósticos</div><div class=\"it\">Habilidades prioritárias</div><div class=\"it\">Indicadores</div><div class=\"it\">Configurações</div></aside><main><div class=\"cab\"><b>Visão geral da rede</b></div><div class=\"corpo\"><div class=\"cards\"><div class=\"card\"><b>61%</b><small>Praticaram na semana</small></div><div class=\"card\"><b>4.180</b><small>Habilidades recuperadas</small></div><div class=\"card\"><b>5</b><small>Escolas que precisam de atenção</small></div></div><div style=\"height:2mm\"></div><div class=\"lst\"><div class=\"li\"><b>Uso por componente (semana)</b><small>Matemática 34% · Língua Portuguesa 29% · Ciências 12% · demais 25%</small></div></div></div></main></div></div><figcaption>Ilustração da tela. A visão geral mostra a prática da semana e as escolas que precisam de atenção.</figcaption></figure><figure><div class=\"colunas\"><div class=\"plot\"><div class=\"grp\"><div class=\"cols\"><span style=\"height:78%;background:#14467A\"><i>78</i></span><span style=\"height:52%;background:#1E8E5A\"><i>52</i></span></div><small>Escola 1</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:71%;background:#14467A\"><i>71</i></span><span style=\"height:47%;background:#1E8E5A\"><i>47</i></span></div><small>Escola 2</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:66%;background:#14467A\"><i>66</i></span><span style=\"height:18%;background:#1E8E5A\"><i>18</i></span></div><small>Escola 3</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:41%;background:#14467A\"><i>41</i></span><span style=\"height:15%;background:#1E8E5A\"><i>15</i></span></div><small>Escola 4</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:28.999999999999996%;background:#14467A\"><i>29</i></span><span style=\"height:9%;background:#1E8E5A\"><i>9</i></span></div><small>Escola 5</small></div></div><div class=\"leg\"><span><i style=\"background:#14467A\"></i>Alunos que praticaram (%)</span><span><i style=\"background:#1E8E5A\"></i>Habilidades recuperadas por 100 alunos</span></div></div><figcaption>Gráfico (exemplo fictício). Prática e recuperação por escola, em 30 dias.</figcaption></figure><figure><div class=\"matriz\"><div class=\"ey\">Habilidades recuperadas</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Pouca prática, boa recuperação</b><small>Ampliar o acesso: mais alunos precisam entrar.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Muita prática, boa recuperação</b><small>Escola de referência. Compartilhar o que faz.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Pouca prática, pouca recuperação</b><small>Problema de acesso. Ver equipamentos, internet e responsáveis. Exemplo: Escolas 4 e 5.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Muita prática, pouca recuperação</b><small>Conteúdo difícil. Apoio pedagógico e formação. Exemplo: Escola 3.</small></div></div><div class=\"ex\">Prática dos alunos</div></div><figcaption>Figura. Como interpretar prática e recuperação em conjunto.</figcaption></figure><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Matemática</span><span class=\"tr\"><span class=\"br\" style=\"width:85%;background:#14467A\"></span></span><span class=\"vl\">34%</span></div><div class=\"ln\"><span class=\"rt\">Língua Portuguesa</span><span class=\"tr\"><span class=\"br\" style=\"width:72.5%;background:#14467A\"></span></span><span class=\"vl\">29%</span></div><div class=\"ln\"><span class=\"rt\">Ciências</span><span class=\"tr\"><span class=\"br\" style=\"width:30%;background:#14467A\"></span></span><span class=\"vl\">12%</span></div><div class=\"ln\"><span class=\"rt\">História</span><span class=\"tr\"><span class=\"br\" style=\"width:20%;background:#14467A\"></span></span><span class=\"vl\">8%</span></div><div class=\"ln\"><span class=\"rt\">Geografia</span><span class=\"tr\"><span class=\"br\" style=\"width:17.5%;background:#14467A\"></span></span><span class=\"vl\">7%</span></div><div class=\"ln\"><span class=\"rt\">Língua Inglesa</span><span class=\"tr\"><span class=\"br\" style=\"width:12.5%;background:#14467A\"></span></span><span class=\"vl\">5%</span></div><div class=\"ln\"><span class=\"rt\">Outros componentes</span><span class=\"tr\"><span class=\"br\" style=\"width:12.5%;background:#14467A\"></span></span><span class=\"vl\">5%</span></div></div><figcaption>Gráfico (exemplo fictício). Uso por componente na semana. Um uso concentrado em poucas matérias pede incentivo às demais.</figcaption></figure><div class=\"caso\"><div class=\"tt\">Exemplo de uso · escola com pouca prática</div><p><b>Situação.</b> Nos indicadores de 30 dias, a Escola 5 tem 29% de alunos praticando, bem abaixo da rede.</p><p><b>O que fazer.</b></p><ol><li>Veja com a direção quantos alunos receberam o acesso e quantos têm responsável vinculado.</li><li>Verifique se há problema de equipamento ou de internet.</li><li>Combine um dia de entrega de acessos e uma reunião com os responsáveis.</li><li>Acompanhe o indicador nas quatro semanas seguintes.</li></ol><p><b>Resultado esperado.</b> A prática da escola se aproxima da média da rede.</p></div>"},{"id":"c9","titulo":"Formação das equipes","html":"<p>A plataforma traz o material de formação na tela <b>Formação</b>. Cada perfil vê os guias dele, lê na tela e pode baixar em PDF.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Perfil</th><th>Material</th><th>Carga sugerida</th></tr></thead><tbody><tr><td>Professores</td><td>Guia do professor e guia de ética e uso responsável</td><td>4 h + 2 h</td></tr><tr><td>Coordenação e direção</td><td>Guia da coordenação e da direção e guia de ética</td><td>6 h + 2 h</td></tr><tr><td>Secretaria</td><td>Este guia e guia de ética</td><td>8 h + 2 h</td></tr></tbody></table></div><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Ler o guia</b><small>na plataforma ou em PDF</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Oficina prática</b><small>na escola, com os dados reais</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Verificação</b><small>questões ao final do guia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Registro</b><small>lista de presença e declaração</small></div></div><figcaption>Figura. A trilha de formação de cada servidor.</figcaption></figure><div class=\"nota\"><b>Onde disponibilizar</b><br/>Além da tela Formação, a Secretaria pode publicar os guias no seu ambiente virtual de aprendizagem ou na intranet. O plano de formação descreve as formas de fazer isso.</div>"},{"id":"c10","titulo":"Rotina da Secretaria","html":"<figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Olhar</b><small>Ver a visão geral e os indicadores por escola.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Escolher</b><small>Definir as escolas e as habilidades que precisam de apoio.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Agir</b><small>Conversar com as direções e organizar a formação.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Conferir</b><small>Ver, no mês seguinte, o que mudou.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de acompanhamento da rede.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quando</th><th>O que fazer</th></tr></thead><tbody><tr><td>Toda semana</td><td>Ver na Visão geral as escolas que precisam de atenção.</td></tr><tr><td>Todo mês</td><td>Ler os Indicadores por escola e conversar com as direções abaixo da média.</td></tr><tr><td>A cada bimestre</td><td>Ver as Habilidades prioritárias e alinhar com a coordenação a formação de professores.</td></tr><tr><td>Início do ano letivo</td><td>Abrir o novo ano letivo e atualizar escolas, turmas, alunos e atribuições.</td></tr><tr><td>Sempre que mudar a equipe</td><td>Convidar os novos servidores e desativar o acesso de quem saiu.</td></tr></tbody></table></div>"},{"id":"c11","titulo":"Governança e ética na rede","html":"<p>Cabe à Secretaria garantir que a plataforma seja usada, em toda a rede, no interesse dos alunos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Responsabilidade da Secretaria</th></tr></thead><tbody><tr><td>Transparência</td><td>Informar aos responsáveis, na matrícula, que a rede usa a plataforma, para que serve e como acessar.</td></tr><tr><td>Uso dos indicadores</td><td>Orientar as escolas a usar os dados para apoio, e não para ranking ou punição.</td></tr><tr><td>Equidade</td><td>Mapear alunos sem equipamento ou internet e organizar alternativas de acesso na escola.</td></tr><tr><td>Inteligência artificial</td><td>Manter um canal para que as escolas relatem dica inadequada ou conteúdo com erro.</td></tr><tr><td>Acessos</td><td>Revisar periodicamente quem tem acesso e desativar quem saiu.</td></tr><tr><td>Auditoria</td><td>Conferir, na tela Auditoria, as ações sensíveis realizadas na rede.</td></tr></tbody></table></div><p>A plataforma trata de crianças e adolescentes e usa inteligência artificial. Por isso, o uso ético faz parte do trabalho de quem tem acesso de equipe. Os princípios abaixo valem para todos os perfis.</p><div class=\"tb\"><table><thead><tr><th>Princípio</th><th>O que significa na prática</th></tr></thead><tbody><tr><td>Melhor interesse do aluno</td><td>Toda informação é usada para ajudar o aluno a aprender. Não para punir, expor ou comparar.</td></tr><tr><td>Decisão humana</td><td>A inteligência artificial apoia o estudo. As decisões pedagógicas sobre o aluno são sempre de pessoas.</td></tr><tr><td>Transparência</td><td>Aluno e responsáveis sabem que a plataforma existe, para que serve e o que ela mostra.</td></tr><tr><td>Equidade</td><td>Quem não tem equipamento ou internet em casa não pode ser prejudicado. A escola busca alternativas de acesso.</td></tr><tr><td>Sigilo</td><td>Dados de um aluno só são vistos por quem precisa deles para o trabalho.</td></tr><tr><td>Honestidade dos dados</td><td>Ninguém responde pelo aluno nem altera cadastro para melhorar indicadores.</td></tr></tbody></table></div><h3>O que fazer e o que não fazer</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td>Divulgar resultados da rede de forma agregada.</td><td>Divulgar ranking de escolas, professores ou alunos.</td></tr><tr><td>Usar os indicadores para decidir onde apoiar.</td><td>Vincular bonificação ou punição aos indicadores de prática.</td></tr><tr><td>Dar acesso apenas a quem precisa para o trabalho.</td><td>Manter acesso ativo de quem deixou a rede.</td></tr><tr><td>Informar os responsáveis sobre o uso da plataforma.</td><td>Usar os contatos dos responsáveis para outros assuntos.</td></tr><tr><td>Registrar e tratar os incidentes com dados.</td><td>Compartilhar planilhas de alunos por e-mail pessoal ou aplicativo de mensagem.</td></tr></tbody></table></div><h3>Inteligência artificial: o que ela faz e o que não faz</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A inteligência artificial</th><th>Situação</th></tr></thead><tbody><tr><td>Orienta o raciocínio do aluno com perguntas e dicas</td><td>Faz</td></tr><tr><td>Dá retorno sobre o texto do aluno, parágrafo por parágrafo</td><td>Faz</td></tr><tr><td>Entrega a resposta pronta ou reescreve o texto do aluno</td><td>Não faz</td></tr><tr><td>Recebe o nome ou a matrícula do aluno</td><td>Não recebe</td></tr><tr><td>Decide nota, aprovação ou encaminhamento do aluno</td><td>Não decide</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Se algo parecer errado</b><br/>Uma dica inadequada, um conteúdo com erro ou um comportamento estranho da plataforma devem ser comunicados à direção ou à Secretaria. O registro ajuda a corrigir para toda a rede.</div>"},{"id":"c12","titulo":"Proteção de dados: papéis e deveres","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Papel</th><th>Quem é</th><th>O que faz</th></tr></thead><tbody><tr><td>Controlador</td><td>O Município, por meio da Secretaria</td><td>Decide para que os dados são usados e responde por eles.</td></tr><tr><td>Operador</td><td>A empresa fornecedora da plataforma</td><td>Trata os dados segundo as instruções do Município.</td></tr><tr><td>Encarregado</td><td>Pessoa indicada por cada parte</td><td>Recebe pedidos dos titulares e comunicações da autoridade de proteção de dados.</td></tr><tr><td>Titular</td><td>O aluno, representado pelo responsável, e os servidores</td><td>Pode pedir acesso, correção e eliminação dos dados.</td></tr></tbody></table></div><p>A Lei Geral de Proteção de Dados (Lei nº 13.709/2018) dá proteção reforçada aos dados de crianças e adolescentes. O Município é o responsável pelos dados da rede, e cada servidor responde pelo uso que faz do seu acesso.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dado</th><th>Quem vê</th><th>Cuidado</th></tr></thead><tbody><tr><td>Nome, turma e evolução do aluno</td><td>Professores da turma, direção, coordenação e Secretaria</td><td>Usar só para fins pedagógicos e de gestão.</td></tr><tr><td>Contato dos responsáveis</td><td>Direção e Secretaria</td><td>Não repassar a terceiros nem usar para outros assuntos.</td></tr><tr><td>Respostas e textos do aluno</td><td>Professores da turma</td><td>Não divulgar, mesmo como bom exemplo, sem autorização.</td></tr><tr><td>Seu usuário e senha</td><td>Só você</td><td>Não emprestar. Sair da conta em computador compartilhado.</td></tr></tbody></table></div><ul><li>Não publique telas com nome de aluno em redes sociais ou grupos de mensagens.</li><li>Para mostrar a plataforma em reuniões abertas, use dados de exemplo ou oculte os nomes.</li><li>Os dados dos alunos não são usados para publicidade nem cedidos a terceiros.</li><li>Quando um servidor deixa a escola, a direção ou a Secretaria desativa o acesso dele.</li></ul><div class=\"nota alerta\"><b>Incidente com dados</b><br/>Acesso indevido, senha compartilhada, tela exposta ou dado enviado à pessoa errada devem ser comunicados no mesmo dia à direção, que avisa a Secretaria. A Secretaria tem um encarregado de dados para tratar o caso.</div>"},{"id":"c13","titulo":"Situações e soluções","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>O que fazer</th></tr></thead><tbody><tr><td>A planilha de importação foi recusada.</td><td>Conferir os nomes das colunas e os campos obrigatórios e importar novamente.</td></tr><tr><td>Alunos apareceram em turma errada.</td><td>Corrigir a planilha de origem e reimportar, ou ajustar em Turmas e alunos.</td></tr><tr><td>Um professor não recebeu o convite.</td><td>Conferir o e-mail em Servidores e convites e reenviar.</td></tr><tr><td>A coordenação não vê as escolas.</td><td>Vincular as escolas à coordenação.</td></tr><tr><td>Uma escola pede identidade diferente.</td><td>A identidade vale para a rede inteira.</td></tr><tr><td>A integração parou de atualizar.</td><td>Ver o histórico de chamadas em Integrações e acionar a equipe técnica.</td></tr><tr><td>Um servidor saiu da rede.</td><td>Desativar o acesso em Servidores e convites.</td></tr><tr><td>Um responsável pede os dados do aluno.</td><td>Encaminhar ao encarregado de dados da Secretaria.</td></tr></tbody></table></div>"},{"id":"c14","titulo":"A governança do programa","html":"<p>O reforço escolar envolve o setor pedagógico, o administrativo, a tecnologia, as escolas e as famílias. Sem uma instância que reúna essas partes, cada uma resolve o seu pedaço e os problemas ficam entre elas.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Papel</th><th>Quem costuma exercer</th><th>Responsabilidades</th></tr></thead><tbody><tr><td>Responsável pelo programa</td><td>Dirigente do setor pedagógico</td><td>Define prioridades, acompanha os indicadores e responde ao Secretário.</td></tr><tr><td>Coordenação da implantação</td><td>Servidor designado</td><td>Organiza cadastros, calendário, formação e comunicação com as escolas.</td></tr><tr><td>Referência pedagógica</td><td>Equipe de currículo e formação</td><td>Lê as habilidades prioritárias e orienta a formação.</td></tr><tr><td>Referência de tecnologia</td><td>Setor de tecnologia do Município</td><td>Cuida de conectividade, equipamentos, integrações e segurança.</td></tr><tr><td>Encarregado de dados</td><td>Encarregado do Município</td><td>Orienta sobre proteção de dados e atende os titulares.</td></tr><tr><td>Gestor e fiscal do contrato</td><td>Servidores designados</td><td>Acompanham a execução e atestam o que foi entregue.</td></tr><tr><td>Multiplicadores</td><td>Servidores da rede</td><td>Apoiam as escolas no dia a dia.</td></tr><tr><td>Diretores</td><td>Gestores escolares</td><td>Garantem o uso na escola e informam as dificuldades.</td></tr></tbody></table></div><h3>A reunião mensal do programa</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Pauta</th></tr></thead><tbody><tr><td>10 min</td><td>Encaminhamentos da reunião anterior.</td></tr><tr><td>20 min</td><td>Indicadores do mês: prática e recuperação, por grupo de escolas.</td></tr><tr><td>20 min</td><td>Escolas que precisam de apoio e o que será feito.</td></tr><tr><td>15 min</td><td>Pendências de cadastro, acesso, equipamento e conexão.</td></tr><tr><td>15 min</td><td>Formação e comunicação do mês seguinte.</td></tr><tr><td>10 min</td><td>Encaminhamentos, com responsável e prazo.</td></tr></tbody></table></div><div class=\"nota\"><b>Registro</b><br/>Uma ata curta de cada reunião, com os encaminhamentos, forma a memória do programa e serve à prestação de contas.</div>"},{"id":"c15","titulo":"Implantar por fases","html":"<p>Implantar em todas as escolas ao mesmo tempo é possível, mas exige que cadastros, equipamentos e formação estejam prontos em toda a rede. Muitas redes preferem começar por um grupo de escolas, aprender e expandir.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Fase</th><th>O que acontece</th><th>O que se aprende</th><th>Critério para avançar</th></tr></thead><tbody><tr><td>Preparação</td><td>Cadastros, calendário, equipe e comunicação.</td><td>A qualidade dos dados da rede.</td><td>Planilhas importadas sem pendências.</td></tr><tr><td>Primeiro grupo</td><td>Algumas escolas, de perfis diferentes.</td><td>Dificuldades de acesso, de conexão e de rotina.</td><td>Maioria dos alunos praticando e professores usando o mapa.</td></tr><tr><td>Expansão</td><td>Demais escolas, em ondas.</td><td>Como apoiar muitas escolas ao mesmo tempo.</td><td>Multiplicadores atuando e pendências sob controle.</td></tr><tr><td>Consolidação</td><td>Uso regular em toda a rede.</td><td>O que mantém o uso ao longo do ano.</td><td>Indicadores estáveis e formação continuada em curso.</td></tr></tbody></table></div><h3>Como escolher o primeiro grupo</h3><ul><li>Escolas de tamanhos e regiões diferentes.</li><li>Pelo menos uma com boa conexão e uma com conexão limitada.</li><li>Diretores dispostos a relatar o que funciona e o que não funciona.</li><li>Anos iniciais e anos finais representados.</li></ul><h3>Erros comuns na implantação</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Erro</th><th>Consequência</th><th>Como evitar</th></tr></thead><tbody><tr><td>Entregar acessos sem orientar</td><td>Uso alto na primeira semana e queda em seguida.</td><td>Primeira sessão acompanhada em cada turma.</td></tr><tr><td>Cadastro com turmas erradas</td><td>Professores não veem os alunos.</td><td>Conferência com a direção antes da entrega.</td></tr><tr><td>Formar só os diretores</td><td>O professor não sabe o que fazer com o mapa.</td><td>Oficina em cada escola.</td></tr><tr><td>Deixar as famílias para depois</td><td>Responsáveis não acompanham.</td><td>Reunião no primeiro mês.</td></tr><tr><td>Cobrar número antes de garantir acesso</td><td>Desânimo e atalhos.</td><td>Verificar equipamentos e horários primeiro.</td></tr><tr><td>Não ter a quem recorrer</td><td>Dúvidas simples paralisam a escola.</td><td>Multiplicadores e canal de suporte conhecidos.</td></tr></tbody></table></div>"},{"id":"c16","titulo":"A qualidade dos cadastros","html":"<p>Quase todas as dificuldades dos primeiros dias vêm de cadastro: aluno em turma errada, professor sem atribuição, nome duplicado. Conferir antes de importar poupa semanas de correção.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Erro frequente</th><th>Como aparece</th><th>Como prevenir</th></tr></thead><tbody><tr><td>Aluno duplicado</td><td>O mesmo aluno com grafias diferentes.</td><td>Usar a matrícula como chave e padronizar os nomes.</td></tr><tr><td>Aluno em turma errada</td><td>Professor não encontra o aluno.</td><td>Conferir a planilha com a lista de chamada.</td></tr><tr><td>Turma sem professor</td><td>Ninguém vê o mapa da turma.</td><td>Importar as atribuições depois das turmas e conferir.</td></tr><tr><td>Ano ou turno trocado</td><td>O aluno recebe conteúdo de outro ano.</td><td>Validar ano e turno por escola.</td></tr><tr><td>Aluno que já saiu</td><td>Indicadores de prática mais baixos do que o real.</td><td>Atualizar antes da importação e a cada mês.</td></tr><tr><td>Servidor com perfil errado</td><td>Acesso a mais ou a menos do que deveria.</td><td>Conferir o perfil no convite.</td></tr><tr><td>E-mail incorreto</td><td>O convite não chega.</td><td>Usar o e-mail institucional e confirmar com a escola.</td></tr></tbody></table></div><h3>Conferência em três tempos</h3><ol class=\"passos\"><li><b>Antes da importação:</b> cada direção confere a planilha da própria escola.</li><li><b>Depois da importação:</b> a Secretaria compara os totais com a matrícula oficial.</li><li><b>Todo mês:</b> as direções atualizam entradas, saídas e mudanças de turma.</li></ol><ul class=\"chk\"><li><span></span>O total de alunos por escola confere com a matrícula.</li><li><span></span>Toda turma tem pelo menos um professor atribuído.</li><li><span></span>Todo professor vê as suas turmas.</li><li><span></span>Não há alunos sem turma.</li><li><span></span>Os servidores que saíram foram desativados.</li><li><span></span>As planilhas usadas foram guardadas em local seguro e apagadas dos computadores pessoais.</li></ul><div class=\"nota alerta\"><b>Planilhas têm dados pessoais</b><br/>As planilhas de alunos e de servidores não circulam por aplicativos de mensagens nem por e-mail pessoal. Depois da importação, ficam apenas no repositório oficial da Secretaria.</div>"},{"id":"c17","titulo":"Conectividade e equipamentos","html":"<p>O reforço funciona em tablet, celular e computador. O que a rede precisa garantir é que cada escola tenha condições mínimas para as sessões presenciais e que os alunos sem acesso em casa tenham onde estudar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Item</th><th>O que levantar em cada escola</th><th>O que fazer com a informação</th></tr></thead><tbody><tr><td>Conexão</td><td>Se há internet, onde o sinal chega e quantos equipamentos funcionam ao mesmo tempo.</td><td>Priorizar as escolas sem condição mínima. Definir os espaços de uso.</td></tr><tr><td>Equipamentos</td><td>Quantos há, em que estado e onde ficam guardados.</td><td>Definir o formato de uso: turma inteira, rodízio ou estação.</td></tr><tr><td>Energia e guarda</td><td>Tomadas, carregamento e local seguro.</td><td>Adequar antes da entrega dos equipamentos.</td></tr><tr><td>Pessoa de referência</td><td>Quem cuida dos equipamentos e dos acessos.</td><td>Formar e manter o contato atualizado.</td></tr><tr><td>Alunos sem acesso em casa</td><td>Quantos são, por turma.</td><td>Dimensionar horários de uso na escola.</td></tr></tbody></table></div><h3>Suporte às escolas</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Nível</th><th>Quem atende</th><th>Exemplos</th></tr></thead><tbody><tr><td>Na escola</td><td>Direção e pessoa de referência</td><td>Novo acesso, aluno em turma errada, dúvida de uso.</td></tr><tr><td>Na Secretaria</td><td>Coordenação da implantação e multiplicadores</td><td>Cadastro, perfis, convites, orientação pedagógica.</td></tr><tr><td>Tecnologia do Município</td><td>Setor de tecnologia</td><td>Conexão, equipamentos, integrações.</td></tr><tr><td>Fornecedora</td><td>Suporte da plataforma</td><td>Falha do sistema, erro de conteúdo, dúvidas técnicas.</td></tr></tbody></table></div><ul><li>A escola sabe a quem recorrer em cada caso.</li><li>Os chamados são registrados, com data e solução.</li><li>Problemas que se repetem viram orientação para toda a rede.</li><li>Erros de conteúdo e dicas inadequadas do tutor são comunicados à fornecedora com a descrição do que ocorreu.</li></ul><div class=\"nota\"><b>Equipamentos são patrimônio</b><br/>Entrega, guarda, manutenção e baixa seguem as regras de patrimônio do Município ou as condições do contrato, conforme a origem dos equipamentos.</div>"},{"id":"c18","titulo":"Indicadores do programa","html":"<p>Dois indicadores resumem o programa: a prática, que mostra se os alunos estudam, e a recuperação, que mostra se aprendem. Os demais ajudam a explicar esses dois.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Indicador</th><th>O que mostra</th><th>Para que usar</th><th>Cuidado</th></tr></thead><tbody><tr><td>Prática</td><td>Proporção de alunos que estudaram no período.</td><td>Ver onde o reforço chega.</td><td>Depende do acesso. Ler junto com as condições da escola.</td></tr><tr><td>Recuperação</td><td>Habilidades em que alunos chegaram a Domina.</td><td>Ver onde há aprendizagem.</td><td>Leva algumas semanas para aparecer.</td></tr><tr><td>Habilidades prioritárias</td><td>Onde há mais alunos em Ainda não.</td><td>Orientar currículo e formação.</td><td>Olhar por ano e componente.</td></tr><tr><td>Responsáveis com conta</td><td>Famílias que acompanham.</td><td>Orientar a comunicação.</td><td>Há famílias sem celular com internet.</td></tr><tr><td>Servidores com acesso ativo</td><td>Equipe que usa.</td><td>Orientar a formação.</td><td>Acesso não é uso pedagógico.</td></tr></tbody></table></div><figure><div class=\"matriz\"><div class=\"ey\">Recuperação</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Pouca prática, boa recuperação</b><small>Quem estuda avança. Ampliar o acesso.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Muita prática, boa recuperação</b><small>Reconhecer e aprender com essas escolas.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Pouca prática, pouca recuperação</b><small>Prioridade de apoio: acesso, rotina e formação.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Muita prática, pouca recuperação</b><small>Apoio pedagógico: pré-requisitos e uso do mapa.</small></div></div><div class=\"ex\">Prática</div></div><figcaption>Figura. Como agrupar as escolas para definir o tipo de apoio.</figcaption></figure><h3>Painel mensal da rede</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Onde olhar</th></tr></thead><tbody><tr><td>Quantos alunos estudaram neste mês?</td><td>Indicadores, por escola.</td></tr><tr><td>Quais escolas caíram em relação ao mês anterior?</td><td>Comparação entre períodos.</td></tr><tr><td>Quais habilidades a rede mais recuperou?</td><td>Indicadores de recuperação.</td></tr><tr><td>Quais continuam em Ainda não para a maioria?</td><td>Habilidades prioritárias.</td></tr><tr><td>Quais escolas precisam de visita?</td><td>Quadrantes de prática e recuperação.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Sem ranking</b><br/>Os indicadores orientam o apoio. Divulgar listas de escolas da melhor para a pior desestimula quem mais precisa de ajuda e incentiva atalhos.</div>"},{"id":"c19","titulo":"Apoio às escolas com baixo uso","html":"<ol class=\"passos\"><li>Identifique as escolas no quadrante de pouca prática e pouca recuperação.</li><li>Antes da visita, levante as condições: conexão, equipamentos, horários, troca de direção.</li><li>Converse com a direção para entender, e não para cobrar.</li><li>Verifique três coisas: os alunos têm acesso? Há horário na escola? Os professores conhecem o mapa?</li><li>Combine de uma a três ações, com prazo.</li><li>Ofereça o que cabe à Secretaria: conexão, equipamento, formação, multiplicador.</li><li>Volte em duas a quatro semanas e veja o indicador com a direção.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Causa encontrada</th><th>Resposta da Secretaria</th></tr></thead><tbody><tr><td>Conexão insuficiente</td><td>Priorizar a escola nas ações de conectividade. Orientar o uso em estações.</td></tr><tr><td>Poucos equipamentos</td><td>Rever a distribuição. Orientar o rodízio.</td></tr><tr><td>Cadastro com erros</td><td>Corrigir com a direção, na própria visita.</td></tr><tr><td>Professores sem formação</td><td>Oficina na escola, com multiplicador.</td></tr><tr><td>Direção nova</td><td>Acompanhamento próximo no primeiro bimestre.</td></tr><tr><td>Muitos alunos sem acesso em casa</td><td>Apoiar a organização de horários no contraturno.</td></tr><tr><td>Famílias não informadas</td><td>Apoiar a reunião de responsáveis.</td></tr><tr><td>Problemas de frequência</td><td>Articular busca ativa com a rede de proteção.</td></tr></tbody></table></div><h3>Aprender com quem vai bem</h3><ul><li>Visite também as escolas com boa prática e boa recuperação.</li><li>Pergunte o que fazem de diferente.</li><li>Registre as práticas em uma página.</li><li>Convide a direção a apresentar na reunião de diretores.</li><li>Aproxime escolas vizinhas para troca de experiências.</li></ul><div class=\"nota\"><b>Apoio antes de cobrança</b><br/>Uma escola que recebe ajuda concreta responde melhor do que uma escola que recebe um ofício.</div>"},{"id":"c20","titulo":"Comunicação com a rede e com a cidade","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Público</th><th>O que precisa saber</th><th>Canal</th><th>Frequência</th></tr></thead><tbody><tr><td>Diretores</td><td>Calendário, pendências, indicadores da escola.</td><td>Reunião de diretores e envio semanal.</td><td>Semanal e mensal</td></tr><tr><td>Professores</td><td>O que é o reforço, o papel de cada um, boas práticas.</td><td>Oficinas, guias e tela Formação.</td><td>Na implantação e a cada bimestre</td></tr><tr><td>Responsáveis</td><td>Para que serve, como acompanhar, como ajudar.</td><td>Reuniões nas escolas e comunicados.</td><td>No início e a cada bimestre</td></tr><tr><td>Conselhos</td><td>Objetivos, alcance e resultados.</td><td>Apresentação em reunião.</td><td>Semestral</td></tr><tr><td>Sociedade</td><td>O que o Município oferece e o que já alcançou.</td><td>Canais oficiais da Prefeitura.</td><td>Em marcos do programa</td></tr></tbody></table></div><h3>Como falar dos resultados</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Evite</th></tr></thead><tbody><tr><td>Informar números da rede, com a data e a fonte.</td><td>Prometer resultados que não dependem só do reforço.</td></tr><tr><td>Explicar o que cada número significa.</td><td>Divulgar comparações entre escolas.</td></tr><tr><td>Mostrar o que será feito a partir dos dados.</td><td>Usar imagens ou nomes de alunos sem autorização.</td></tr><tr><td>Reconhecer o trabalho das escolas.</td><td>Atribuir avanços a uma única causa.</td></tr></tbody></table></div><h3>Transparência sobre a inteligência artificial</h3><ul><li>Informe às famílias que a plataforma usa inteligência artificial para orientar o estudo.</li><li>Explique o que ela faz e o que não faz: orienta com dicas, não dá resposta, não atribui nota.</li><li>Informe que o nome e a matrícula do aluno não são enviados à inteligência artificial.</li><li>Indique o canal para dúvidas e pedidos sobre dados pessoais.</li></ul><div class=\"nota\"><b>Uma mensagem, várias vozes</b><br/>Quando o Secretário, os diretores e os professores explicam o reforço com as mesmas palavras, as famílias confiam mais.</div>"},{"id":"c21","titulo":"Acompanhar o contrato","html":"<p>A plataforma é fornecida por contrato. A Lei nº 14.133/2021 determina que a execução seja acompanhada por fiscais designados pela Administração (art. 117). Este capítulo ajuda a equipe pedagógica a colaborar com o fiscal do contrato.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que acompanhar</th><th>Como verificar</th><th>Quem informa</th></tr></thead><tbody><tr><td>Disponibilidade da plataforma</td><td>Registro de dias e horários em que o acesso falhou.</td><td>Escolas e setor de tecnologia</td></tr><tr><td>Licenças em uso</td><td>Número de alunos e servidores cadastrados em relação ao contratado.</td><td>Coordenação da implantação</td></tr><tr><td>Conteúdo</td><td>Cobertura dos anos e componentes previstos. Erros comunicados e corrigidos.</td><td>Equipe pedagógica</td></tr><tr><td>Suporte</td><td>Chamados abertos, prazos de resposta e solução.</td><td>Coordenação da implantação</td></tr><tr><td>Formação</td><td>Materiais entregues e encontros realizados, conforme o contrato.</td><td>Equipe de formação</td></tr><tr><td>Proteção de dados</td><td>Cumprimento das obrigações de tratamento de dados previstas.</td><td>Encarregado de dados</td></tr><tr><td>Relatórios</td><td>Entrega nos prazos previstos.</td><td>Gestor do contrato</td></tr></tbody></table></div><h3>Boas práticas de fiscalização</h3><ul><li>Registrar as ocorrências por escrito, com data.</li><li>Comunicar formalmente à contratada o que precisa ser corrigido.</li><li>Guardar as evidências de entrega: relatórios, listas de presença, telas.</li><li>Atestar apenas o que foi efetivamente entregue.</li><li>Levar ao gestor do contrato o que ultrapassa a competência do fiscal.</li><li>Manter separados o acompanhamento pedagógico e o ateste administrativo, com troca regular de informações.</li></ul><div class=\"nota\"><b>O contrato é a referência</b><br/>Prazos, níveis de serviço, quantidades e obrigações são os que constam do contrato e de seus anexos. Este guia não os substitui.</div>"},{"id":"c22","titulo":"A virada do ano letivo","html":"<p>A passagem de um ano para o outro é o momento de maior risco para os cadastros. Um roteiro evita que os alunos comecem o ano na turma do ano anterior.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th><th>Quando</th></tr></thead><tbody><tr><td>Fechamento</td><td>Conferir os dados finais do ano com as escolas.</td><td>Dezembro</td></tr><tr><td>Novas turmas</td><td>Criar as turmas do novo ano conforme a matrícula.</td><td>Antes do início das aulas</td></tr><tr><td>Alunos</td><td>Importar ou atualizar os alunos nas novas turmas. O histórico de aprendizagem acompanha o aluno.</td><td>Antes do início das aulas</td></tr><tr><td>Saídas</td><td>Registrar alunos que concluíram a etapa ou deixaram a rede.</td><td>Janeiro e fevereiro</td></tr><tr><td>Novos alunos</td><td>Incluir e entregar os acessos.</td><td>Primeira semana</td></tr><tr><td>Servidores</td><td>Desativar quem saiu, convidar quem chegou, refazer as atribuições.</td><td>Semana pedagógica</td></tr><tr><td>Formação</td><td>Orientar os novos servidores e relembrar os demais.</td><td>Semana pedagógica</td></tr><tr><td>Famílias</td><td>Entregar códigos aos responsáveis dos novos alunos.</td><td>Primeiro mês</td></tr><tr><td>Diagnóstico inicial</td><td>Definir se a rede abrirá um diagnóstico de início de ano.</td><td>Primeiro mês</td></tr></tbody></table></div><h3>O que o histórico permite</h3><ul><li>O professor do novo ano vê o que a turma já domina desde o primeiro dia.</li><li>A retomada começa pelas habilidades que ficaram em Ainda não.</li><li>A Secretaria compara a rede com ela mesma, de um ano para o outro.</li></ul><ul class=\"chk\"><li><span></span>Nenhuma turma do ano anterior continua ativa.</li><li><span></span>Todos os alunos matriculados aparecem em uma turma.</li><li><span></span>Todos os professores têm atribuição.</li><li><span></span>Os servidores que saíram não têm mais acesso.</li><li><span></span>Os acessos dos novos alunos foram entregues.</li></ul>"},{"id":"c23","titulo":"Avaliar os resultados com cuidado","html":"<p>A Secretaria precisa dizer à cidade o que o programa alcançou. Para isso, vale separar o que os dados mostram do que eles não permitem afirmar.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Pergunta</th><th>Dado que responde</th><th>Limite</th></tr></thead><tbody><tr><td>O reforço chegou aos alunos?</td><td>Prática, por escola e por ano.</td><td>Não diz se o uso foi de qualidade.</td></tr><tr><td>Os alunos recuperaram habilidades?</td><td>Recuperação.</td><td>Mostra o que foi feito na plataforma.</td></tr><tr><td>Onde estão as maiores lacunas?</td><td>Habilidades prioritárias.</td><td>Depende de quantos alunos fizeram o diagnóstico.</td></tr><tr><td>A aprendizagem da rede melhorou?</td><td>Avaliações da rede e nacionais, ao longo dos anos.</td><td>Muitos fatores influenciam, além do reforço.</td></tr><tr><td>As famílias acompanham?</td><td>Responsáveis com conta e retornos recebidos.</td><td>Há famílias que acompanham sem usar a conta.</td></tr></tbody></table></div><h3>Cuidados ao tirar conclusões</h3><ul><li>Compare a rede com ela mesma, em períodos equivalentes.</li><li>Não atribua toda melhora ou toda piora a uma única ação.</li><li>Observe se quem mais praticou foi quem já tinha melhores condições.</li><li>Olhe os grupos: anos iniciais e finais, escolas urbanas e rurais, alunos com e sem acesso em casa.</li><li>Ouça professores e diretores: eles explicam o que os números não mostram.</li><li>Registre os resultados com data, fonte e forma de cálculo.</li></ul><h3>Relatório semestral em duas páginas</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Alcance</td><td>Escolas, turmas, alunos e servidores atendidos.</td></tr><tr><td>Uso</td><td>Prática ao longo dos meses.</td></tr><tr><td>Aprendizagem</td><td>Habilidades recuperadas e habilidades prioritárias.</td></tr><tr><td>Famílias</td><td>Responsáveis com conta e principais retornos.</td></tr><tr><td>Formação</td><td>Servidores formados e encontros realizados.</td></tr><tr><td>Dificuldades</td><td>O que não funcionou e por quê.</td></tr><tr><td>Próximos passos</td><td>O que a Secretaria fará no semestre seguinte.</td></tr></tbody></table></div><div class=\"nota\"><b>Mostrar as dificuldades dá credibilidade</b><br/>Um relatório que só traz boas notícias convence menos do que um que mostra também o que precisa melhorar e o que será feito.</div>"},{"id":"c24","titulo":"Perguntas frequentes da Secretaria","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td>Em que ordem importar as planilhas?</td><td>Escolas, turmas, alunos, servidores e atribuições, conforme as etapas da tela Implantação.</td></tr><tr><td>Posso importar de novo depois de corrigir?</td><td>Sim. Corrija a planilha e envie novamente, conferindo o resultado.</td></tr><tr><td>Quem pode convidar servidores?</td><td>O perfil da Secretaria, na tela Servidores e convites.</td></tr><tr><td>Um diretor pode ver outra escola?</td><td>Não. O perfil de direção vê a própria escola.</td></tr><tr><td>A coordenação da rede vê todas as escolas?</td><td>Sim, nas telas do perfil de coordenação.</td></tr><tr><td>Como a rede aparece para os usuários?</td><td>Com o nome e a identidade definidos em Identidade da rede.</td></tr><tr><td>O que a inteligência artificial recebe dos alunos?</td><td>O conteúdo do estudo. O nome e a matrícula não são enviados.</td></tr><tr><td>Podemos usar os dados para pesquisa?</td><td>Apenas dentro das regras de proteção de dados, com orientação do encarregado.</td></tr><tr><td>Um responsável pediu os dados do filho.</td><td>Encaminhe ao encarregado de dados, que atende no prazo legal.</td></tr><tr><td>Como desligar um servidor que saiu?</td><td>Desative o acesso na tela Servidores e convites.</td></tr><tr><td>Onde vejo quem fez o quê?</td><td>Na tela Auditoria.</td></tr><tr><td>A plataforma substitui a recuperação prevista em lei?</td><td>Não. Ela apoia a recuperação organizada pelas escolas.</td></tr></tbody></table></div>"},{"id":"c25","titulo":"Mais situações da Secretaria","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a escola com conexão fraca</div><p><b>Situação.</b> Uma escola rural só tem sinal em uma sala e apresenta a menor prática da rede.</p><p><b>O que fazer.</b></p><ol><li>Levante as condições antes de cobrar.</li><li>Oriente o uso em estações, na sala com sinal.</li><li>Monte com a direção uma grade em que todas as turmas passem pela sala.</li><li>Inclua a escola nas prioridades de conectividade.</li><li>Acompanhe o indicador em comparação com a própria escola.</li></ol><p><b>Resultado esperado.</b> A prática sobe dentro do que a estrutura permite, e a escola não é comparada com as demais.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · os professores que não viam as turmas</div><p><b>Situação.</b> Na primeira semana, dezenas de professores informam que a lista de turmas está vazia.</p><p><b>O que fazer.</b></p><ol><li>Verifique se as atribuições foram importadas.</li><li>Confira uma escola por amostra, com a direção.</li><li>Corrija a planilha de atribuições e importe de novo.</li><li>Avise as escolas quando estiver resolvido.</li><li>Inclua a conferência das atribuições no roteiro de implantação.</li></ol><p><b>Resultado esperado.</b> Os professores passam a ver as turmas, e o erro não se repete na virada do ano.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o pedido da imprensa</div><p><b>Situação.</b> Um veículo local pede a lista das escolas com melhores e piores resultados no reforço.</p><p><b>O que fazer.</b></p><ol><li>Informe os dados gerais da rede.</li><li>Explique que a Secretaria não divulga comparações entre escolas e por quê.</li><li>Ofereça exemplos de práticas, com autorização das escolas.</li><li>Não forneça dados nem imagens de alunos.</li></ol><p><b>Resultado esperado.</b> A cidade é informada sem expor escolas nem alunos.</p></div><div class=\"pratica\"><div class=\"tt\">Para praticar · o próximo mês do programa</div><div class=\"q\"><b>1.</b> Quais escolas estão no quadrante de pouca prática e pouca recuperação?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que apoio cada uma receberá e de quem?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Que escola pode apresentar uma boa prática na próxima reunião de diretores?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c26","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"Implantação da rede em oito etapas\"</td><td>Em que etapa estamos? O que ainda está pendente?</td></tr><tr><td>2</td><td>O menu, as decisões de configuração e as integrações</td><td>Que decisões já tomamos? Quais precisam ser revistas?</td></tr><tr><td>3</td><td>De \"Como acompanhar a rede\" até \"Proteção de dados\"</td><td>Como lemos os indicadores hoje? Quem é o nosso encarregado de dados?</td></tr><tr><td>4</td><td>De \"A governança do programa\" até \"Conectividade e equipamentos\"</td><td>Quem responde por cada parte do programa? Como está a qualidade dos cadastros?</td></tr><tr><td>5</td><td>De \"Indicadores do programa\" até o final</td><td>Que escolas precisam de apoio? O que vamos apresentar no relatório do semestre?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c27","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Qual é a primeira etapa do assistente de implantação?</p><ol type=\"a\"><li>Turmas e alunos.</li><li>Escolas.</li><li>Cartões de acesso.</li><li>Servidores.</li></ol></div><div class=\"qz\"><p><b>2.</b> Para manter o reforço independente da escola, a trilha após o diagnóstico deve ser:</p><ol type=\"a\"><li>Sugerida ao professor.</li><li>Atribuída direto ao aluno.</li><li>Aprovada pela direção.</li><li>Definida pelo responsável.</li></ol></div><div class=\"qz\"><p><b>3.</b> Pouca prática e pouca recuperação de habilidades em uma escola indicam principalmente:</p><ol type=\"a\"><li>Conteúdo difícil.</li><li>Problema de acesso.</li><li>Excesso de diagnósticos.</li><li>Erro na identidade da rede.</li></ol></div><div class=\"qz\"><p><b>4.</b> Na proteção de dados, o Município é:</p><ol type=\"a\"><li>Operador.</li><li>Titular.</li><li>Controlador.</li><li>Encarregado.</li></ol></div><div class=\"qz\"><p><b>5.</b> Qual prática respeita a ética no uso dos indicadores?</p><ol type=\"a\"><li>Ranking de escolas no site.</li><li>Bonificação por prática.</li><li>Divulgação agregada e apoio às escolas abaixo da média.</li><li>Punição a professores.</li></ol></div><div class=\"qz\"><p><b>6.</b> A chave de integração deve ser:</p><ol type=\"a\"><li>Enviada a todas as escolas.</li><li>Guardada em local seguro e trocada quando alguém da equipe técnica sair.</li><li>Publicada na intranet.</li><li>Igual à senha do gestor.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Escolas. A rede começa pelo cadastro das escolas.</p><p><b>2.</b> b) Atribuída direto ao aluno. É uma decisão da tela Configurações.</p><p><b>3.</b> b) Problema de acesso. Ver equipamentos, internet e responsáveis.</p><p><b>4.</b> c) Controlador. O Município decide o uso dos dados e responde por eles.</p><p><b>5.</b> c) Divulgação agregada e apoio às escolas abaixo da média. Os dados servem para decidir onde apoiar.</p><p><b>6.</b> b) Guardada em local seguro e trocada quando alguém da equipe técnica sair. Ela dá acesso aos dados da rede.</p></div>"},{"id":"c28","titulo":"Glossário","html":"<dl><dt>BNCC</dt><dd>Base Nacional Comum Curricular. Define as habilidades que o aluno deve desenvolver em cada ano e componente.</dd><dt>Componente curricular</dt><dd>Cada matéria do currículo: Língua Portuguesa, Matemática, Ciências e as demais.</dd><dt>Controlador</dt><dd>Quem decide para que os dados pessoais são usados. Na rede municipal, é o Município.</dd><dt>Diagnóstico</dt><dd>Conjunto curto de questões que mostra quais habilidades o aluno já domina.</dd><dt>Habilidade</dt><dd>O que o aluno deve saber fazer. É a unidade que a plataforma acompanha.</dd><dt>Habilidade recuperada</dt><dd>Habilidade em que o aluno saiu de Ainda não ou Quase lá e chegou a Domina.</dd><dt>Integração</dt><dd>Troca automática de dados entre a plataforma e outro sistema da Secretaria.</dd><dt>Login único</dt><dd>Entrada com a conta institucional que a rede já usa.</dd><dt>Nível de domínio</dt><dd>Situação do aluno em uma habilidade: Ainda não, Quase lá ou Domina.</dd><dt>Operador</dt><dd>Quem trata os dados em nome do controlador.</dd><dt>Pré-requisito</dt><dd>Habilidade anterior que serve de base para outra.</dd><dt>Responsável</dt><dd>Adulto que cuida do aluno e o acompanha na plataforma.</dd><dt>Trilha</dt><dd>Sequência de estudo de uma habilidade, em cinco etapas.</dd><dt>Tutor</dt><dd>Apoio com inteligência artificial que orienta o aluno com perguntas e dicas.</dd></dl>"},{"id":"c29","titulo":"Guia rápido","html":"<div class=\"rapido\"><h3>Implantação</h3><p>Escolas · Ano letivo · Matérias · Servidores · Turmas e alunos · Professores nas turmas · Cartões de acesso · Revisão</p><h3>Toda semana</h3><ol class=\"passos\"><li><b>Visão geral</b>: veja as escolas que precisam de atenção.</li><li><b>Indicadores</b>: compare prática e recuperação por escola.</li><li>Converse com as direções abaixo da média.</li></ol><h3>Lembre-se</h3><ul><li>Cadastro certo evita a maior parte das dúvidas.</li><li>Mudança de configuração vale para toda a rede.</li><li>Indicador serve para apoiar, não para ranking.</li><li>Acesso de quem saiu deve ser desativado.</li><li>Chave de integração é dado sensível.</li></ul></div>"},{"id":"c30","titulo":"Avaliação final","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> A reunião mensal do programa serve para:</p><ol type=\"a\"><li>Divulgar o ranking das escolas.</li><li>Ler os indicadores e definir apoios, com encaminhamentos.</li><li>Substituir a formação.</li><li>Aprovar notas.</li></ol></div><div class=\"qz\"><p><b>2.</b> Antes de entregar os acessos, é essencial:</p><ol type=\"a\"><li>Cobrar metas.</li><li>Conferir os cadastros com as direções.</li><li>Publicar os resultados.</li><li>Dispensar a formação.</li></ol></div><div class=\"qz\"><p><b>3.</b> Planilhas de alunos devem:</p><ol type=\"a\"><li>Circular em grupos de mensagens.</li><li>Ficar apenas no repositório oficial da Secretaria.</li><li>Ser impressas e afixadas.</li><li>Ser enviadas por e-mail pessoal.</li></ol></div><div class=\"qz\"><p><b>4.</b> Escolas com pouca prática e pouca recuperação precisam de:</p><ol type=\"a\"><li>Ofício de cobrança.</li><li>Apoio prioritário em acesso, rotina e formação.</li><li>Corte de equipamentos.</li><li>Divulgação pública.</li></ol></div><div class=\"qz\"><p><b>5.</b> O fiscal do contrato deve atestar:</p><ol type=\"a\"><li>O que foi prometido.</li><li>Apenas o que foi efetivamente entregue.</li><li>O que a escola pedir.</li><li>Nada.</li></ol></div><div class=\"qz\"><p><b>6.</b> Na virada do ano, o histórico de aprendizagem do aluno:</p><ol type=\"a\"><li>É apagado.</li><li>Acompanha o aluno na nova turma.</li><li>Fica com o professor antigo.</li><li>Vira nota.</li></ol></div><div class=\"qz\"><p><b>7.</b> Ao divulgar resultados, a Secretaria:</p><ol type=\"a\"><li>Compara escolas publicamente.</li><li>Informa números da rede, com data e fonte.</li><li>Usa nomes de alunos.</li><li>Atribui tudo ao reforço.</li></ol></div><div class=\"qz\"><p><b>8.</b> Um responsável pede os dados do filho. A Secretaria:</p><ol type=\"a\"><li>Nega.</li><li>Encaminha ao encarregado de dados.</li><li>Pede pagamento.</li><li>Ignora.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Ler os indicadores e definir apoios, com encaminhamentos. Indicadores e decisões.</p><p><b>2.</b> b) Conferir os cadastros com as direções. Cadastro errado trava os primeiros dias.</p><p><b>3.</b> b) Ficar apenas no repositório oficial da Secretaria. Contêm dados pessoais.</p><p><b>4.</b> b) Apoio prioritário em acesso, rotina e formação. Apoio antes de cobrança.</p><p><b>5.</b> b) Apenas o que foi efetivamente entregue. Com registro e evidências.</p><p><b>6.</b> b) Acompanha o aluno na nova turma. O novo professor vê o que a turma domina.</p><p><b>7.</b> b) Informa números da rede, com data e fonte. Sem ranking e sem exposição.</p><p><b>8.</b> b) Encaminha ao encarregado de dados. É direito do titular.</p></div>"}];
